  "language": "Solidity",
  "sources": {
    "IOPnToken.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract IOPnToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(
        address indexed from,
        address indexed to,
        uint256 value
    );

    event Approval(
        address indexed owner,
        address indexed spender,
        uint256 value
    );

    constructor(
        string memory tokenName,
        string memory tokenSymbol,
        uint256 initialSupply,
        uint8 tokenDecimals,
        address initialOwner
    ) {
        require(
            initialOwner != address(0),
            "Invalid owner"
        );

        require(
            bytes(tokenName).length > 0,
            "Invalid name"
        );

        require(
            bytes(tokenSymbol).length > 0,
            "Invalid symbol"
        );

        require(
            tokenDecimals <= 18,
            "Invalid decimals"
        );

        name = tokenName;
        symbol = tokenSymbol;
        decimals = tokenDecimals;

        uint256 supply =
            initialSupply *
            (10 ** uint256(tokenDecimals));

        totalSupply = supply;

        balanceOf[initialOwner] = supply;

        emit Transfer(
            address(0),
            initialOwner,
            supply
        );
    }

    function transfer(
        address to,
        uint256 amount
    ) external returns (bool) {
        require(
            to != address(0),
            "Invalid recipient"
        );

        require(
            balanceOf[msg.sender] >= amount,
            "Insufficient balance"
        );

        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;

        emit Transfer(
            msg.sender,
            to,
            amount
        );

        return true;
    }

    function approve(
        address spender,
        uint256 amount
    ) external returns (bool) {
        require(
            spender != address(0),
            "Invalid spender"
        );

        allowance[msg.sender][spender] = amount;

        emit Approval(
            msg.sender,
            spender,
            amount
        );

        return true;
    }

    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) external returns (bool) {
        require(
            to != address(0),
            "Invalid recipient"
        );

        require(
            balanceOf[from] >= amount,
            "Insufficient balance"
        );

        uint256 allowed =
            allowance[from][msg.sender];

        require(
            allowed >= amount,
            "Insufficient allowance"
        );

        balanceOf[from] -= amount;
        balanceOf[to] += amount;

        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] =
                allowed - amount;
        }

        emit Transfer(
            from,
            to,
            amount
        );

        return true;
    }
}"
    }
  },
  "settings": {
    "optimizer": {
